let scope='all',filter='all',selectedCategories=[],query='',categories=[],contacts=[],phoneSorting=[],appointments=[],reminders=[],internal=[],vehicles=[],homeEpoch=0,refreshTimer,legacyMigrationTimer,legacyMigrationBusy=false,lastError='',pairDialog='';
const cleanObject=x=>{const r=structuredClone(x);Object.keys(r).filter(k=>k[0]==='_').forEach(k=>delete r[k]);return r;};
