    $$('[data-cat-name]',box).forEach(input=>input.oninput=()=>rows[Number(input.dataset.catName)].name=input.value);
    $$('[data-cat-color]',box).forEach(input=>input.oninput=()=>{rows[Number(input.dataset.catColor)].color=input.value;input.closest('.hub-category-editor').style.setProperty('--hub-color',input.value);});
