function deviceDraftKey(owner,threadId,address=''){return DEVICE_DRAFT_PREFIX+encodeURIComponent(owner)+'|'+encodeURIComponent(H.phone(address)||threadId);}
function readDeviceDraft(key){try{const value=JSON.parse(localStorage.getItem(key)||'null');if(!value||Date.now()-Number(value.savedAt||0)>DEVICE_DRAFT_MAX_AGE){localStorage.removeItem(key);return '';}return String(value.text||'').slice(0,16000);}catch{return '';}}
