function updateBadge(){const unread=internal.reduce((n,r)=>n+(r.unread||0),0)+deviceRows().reduce((n,r)=>n+(r.live?(r.unread||0):0),0),nav=$('#chat-nav-btn');if(!nav)return;let badge=$('.hub-nav-badge',nav);if(!badge){badge=document.createElement('b');badge.className='hub-nav-badge';nav.append(badge);}badge.textContent=unread>99?'99+':String(unread);badge.hidden=!unread;let alerts=$('.hub-important-alerts',nav);if(!alerts){alerts=document.createElement('span');alerts.className='hub-important-alerts';nav.append(alerts);}const active=categoryUnreadCounts({importantOnly:true}).filter(item=>item.count>0);alerts.replaceChildren(...active.map(({category,count})=>{const dot=document.createElement('span');dot.className='hub-important-alert-dot';dot.style.setProperty('--hub-color',H.color(category.color)||accent());dot.title=`${category.name} · ${count} unread`;dot.setAttribute('role','img');dot.setAttribute('aria-label',dot.title);return dot;}));alerts.hidden=!active.length;}
