const trustModes=[['ask','Ask Every Time','This computer needs phone approval every time.'],['36h','36 Hours · Default','Foreground LotKeys use renews trust for 36 hours.'],['7d','7 Days','Foreground LotKeys use renews trust for seven days.'],['until-disconnect','Until I Disconnect','For a personal computer. Trust ends when you disconnect or forget it.']];
