function showPairRequest(offer){if(pairDialog||!offer?.sessionId||document.body.dataset.lotkeysLocked==='true')return;const modes=trustModes.map(([id,label])=>`<option value="${id}" ${id==='36h'?'selected':''}>${e(label)}</option>`).join(''),d=modal('Computer wants to connect',`<p class="hub-caption">Confirm that this is the computer in front of you:</p><strong class="hub-request-device">${e(offer.pcName||'Unknown computer')}</strong><div class="hub-pair-code">${e(offer.code)}</div><label class="hub-field">Trust this computer<select id="hub-trust-mode">${modes}</select></label><p class="hub-caption" id="hub-trust-help"></p><div class="hub-end"><button class="hub-btn danger" id="hub-pair-reject">Decline</button><button class="hub-btn primary" id="hub-pair-approve">Approve & Connect</button></div><p class="hub-warning">Approve only when the same four digits are visible on your computer.</p>`);pairDialog='phone:'+offer.sessionId;const select=$('#hub-trust-mode',d),help=$('#hub-trust-help',d),explain=()=>help.textContent=trustModes.find(([id])=>id===select.value)?.[2]||'';select.onchange=explain;explain();d._cleanup=()=>pairDialog='';action($('#hub-pair-reject',d),async()=>{d._dirty=false;await P.rejectPair(offer.sessionId);d.close();toast('Computer connection declined.');});action($('#hub-pair-approve',d),async()=>{const mode=select.value;d._dirty=false;await P.approvePair(offer.sessionId,mode);d.close();toast('Computer connected to this phone.');});}
