function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
async function viewFile(id,fileId,save=false){const c=await S.get('contact',id),f=c?.attachments?.find(x=>x.id===fileId);if(!f)return;const b=await S.blob(id,fileId);if(save||!/^image\/(jpeg|png|webp)$/i.test(f.type)){download(b,f.name);toast('Saved a copy. Open that file to print it; this copy is outside Hub deletion.');return;}const u=URL.createObjectURL(b),d=modal(f.name,`<img class="hub-preview-image" alt="Customer attachment" src="${u}"><div class="hub-end"><button class="hub-btn" id="hub-image-download">Save / print copy</button></div>`);d._cleanup=()=>URL.revokeObjectURL(u);$('#hub-image-download',d).onclick=()=>download(b,f.name);}
async function camera(id,onSaved){if(!navigator.mediaDevices?.getUserMedia)throw Error('In-app camera needs HTTPS and camera support. Choose a file instead.');const d=modal('Camera · private customer attachment',`<video id="hub-camera" class="hub-camera" autoplay muted playsinline></video><img id="hub-capture-preview" class="hub-preview-image" hidden alt="Captured customer photo"><canvas hidden id="hub-camera-canvas"></canvas><p class="hub-caption">LotKeys does not add camera captures to your phone gallery. A temporary capture stays in browser memory until saved to Drive or discarded.</p><div class="hub-end"><button id="hub-capture" class="hub-btn primary">Take photo</button><button id="hub-retake" class="hub-btn" hidden>Retake</button><button id="hub-save-capture" class="hub-btn primary" hidden>Save to customer</button></div><div id="hub-camera-status" class="hub-caption"></div>`);let stream,captured,preview='';d._cleanup=()=>{stream?.getTracks().forEach(t=>t.stop());if(preview)URL.revokeObjectURL(preview);captured=null;};try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920}},audio:false});if(!d.isConnected){stream.getTracks().forEach(t=>t.stop());return;}$('#hub-camera',d).srcObject=stream;}catch(err){report(Error('Camera permission was denied or the camera is unavailable. Use Choose files instead.'),d);return;}action($('#hub-capture',d),async()=>{const v=$('#hub-camera',d),canvas=$('#hub-camera-canvas',d);if(!v.videoWidth)throw Error('The camera preview is not ready.');canvas.width=v.videoWidth;canvas.height=v.videoHeight;canvas.getContext('2d').drawImage(v,0,0);captured=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.92));if(!captured)throw Error('Could not capture this photo.');preview=URL.createObjectURL(captured);$('#hub-capture-preview',d).src=preview;$('#hub-capture-preview',d).hidden=false;v.hidden=true;$('#hub-capture',d).hidden=true;$('#hub-retake',d).hidden=false;$('#hub-save-capture',d).hidden=false;});$('#hub-retake',d).onclick=()=>{URL.revokeObjectURL(preview);preview='';captured=null;$('#hub-capture-preview',d).hidden=true;$('#hub-camera',d).hidden=false;$('#hub-capture',d).hidden=false;$('#hub-retake',d).hidden=true;$('#hub-save-capture',d).hidden=true;};action($('#hub-save-capture',d),async()=>{await S.upload(id,new File([captured],'Customer photo '+new Date().toISOString().replace(/[:.]/g,'-')+'.jpg',{type:'image/jpeg'}),p=>$('#hub-camera-status',d).textContent='Uploading '+p+'%');d.close();await onSaved?.();});}
function vehicleLabel(v){return v?[v.year,v.make,v.model].filter(Boolean).join(' ')+' · STK #'+(v.stock||'—'):'';}
