async function editAppointment(id=null,{contactId='',internalId='',date=H.localDay(),onSaved}={}){await loadLocal();const editOwner=await S.identity();vehicles=await Core.DB.all('vehicles');if(internalId&&!contactId){const c=await chooseContact(internalId);if(!c)return;contactId=c.id;await loadLocal();}const old=id?appointments.find(a=>a.id===id):null;let chosenContact=contacts.find(c=>c.id===(old?.contactId||contactId)),chosenVehicle=vehicles.find(v=>v.id===old?.vehicleId);const now=new Date();now.setMinutes(Math.ceil(now.getMinutes()/15)*15,0,0);const start=old?new Date(old.start):new Date(date+'T'+String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0'));const d=modal(id?'Edit appointment':'New appointment',`<form id="hub-appt-form"><div class="hub-grid"><label class="hub-field full">Customer / contact search<input type="search" id="hub-appt-contact" placeholder="Name, number, email or alias" value="${e(chosenContact?.name||'')}"></label><div class="full hub-select-list" id="hub-appt-contact-results"></div><label class="hub-field full">Vehicle Profile search<input type="search" id="hub-appt-vehicle" placeholder="Year, make, model, STK # or VIN" value="${e(chosenVehicle?vehicleLabel(chosenVehicle):'')}"></label><div class="full hub-select-list" id="hub-appt-vehicle-results"></div><label class="hub-field">Date<input type="date" id="hub-appt-date" required value="${H.localDay(start)}"></label><label class="hub-field">Time<input type="time" id="hub-appt-time" required value="${String(start.getHours()).padStart(2,'0')+':'+String(start.getMinutes()).padStart(2,'0')}"></label><label class="hub-field">Duration (minutes)<input type="number" min="5" max="1440" step="5" id="hub-appt-duration" value="${old?Math.round((Date.parse(old.end)-Date.parse(old.start))/60000):30}"></label><label class="hub-field">Status<select id="hub-appt-status">${['Tentative','Confirmed','Arrived','Completed','Cancelled','No show'].map(x=>`<option ${old?.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="hub-field">Type<select id="hub-appt-kind">${['Test drive','Showroom visit','Phone appointment','Delivery','Follow-up','Other'].map(x=>`<option ${old?.kind===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="hub-field">Location<input id="hub-appt-location" maxlength="300" value="${e(old?.location||'')}"></label><label class="hub-field full">Appointment notes<textarea rows="3" id="hub-appt-notes" maxlength="3000">${e(old?.notes||'')}</textarea></label></div><p class="hub-caption">Choose a result to link it. Saving here does not send an invitation or customer message.</p><div class="hub-end"><button class="hub-btn primary" id="hub-appt-save" type="submit">Save appointment</button></div></form>`);
const renderContact=()=>{const box=$('#hub-appt-contact-results',d),q=$('#hub-appt-contact',d).value;box.innerHTML=chosenContact?`<div class="hub-selected">✓ ${e(chosenContact.name)} · ${e(phoneFor(chosenContact))}</div>`:contacts.filter(c=>H.matches(c,q)).slice(0,8).map(c=>`<button class="hub-btn" type="button" data-appt-c="${e(c.id)}">${e(c.name)} · ${e(phoneFor(c))}</button>`).join('')||'<span class="hub-caption">No matching saved contact. Add the contact from Hub ＋ first.</span>';$$('[data-appt-c]',box).forEach(b=>b.onclick=()=>{chosenContact=contacts.find(c=>c.id===b.dataset.apptC);$('#hub-appt-contact',d).value=chosenContact.name;renderContact();});};$('#hub-appt-contact',d).oninput=()=>{chosenContact=null;renderContact();};renderContact();const renderVehicle=()=>{const box=$('#hub-appt-vehicle-results',d),q=$('#hub-appt-vehicle',d).value.trim().toLowerCase();box.innerHTML=chosenVehicle?`<div class="hub-selected">✓ ${e(vehicleLabel(chosenVehicle))}</div>`:q?vehicles.filter(v=>(vehicleLabel(v)+' '+(v.vin||'')).toLowerCase().includes(q)).slice(0,6).map(v=>`<button class="hub-btn" type="button" data-appt-v="${e(v.id)}">${e(vehicleLabel(v))}</button>`).join('')||'<span class="hub-caption">No matching cached Vehicle Profile.</span>':'<span class="hub-caption">Optional: leave blank for a general appointment.</span>';$$('[data-appt-v]',box).forEach(b=>b.onclick=()=>{chosenVehicle=vehicles.find(v=>v.id===b.dataset.apptV);$('#hub-appt-vehicle',d).value=vehicleLabel(chosenVehicle);renderVehicle();});};$('#hub-appt-vehicle',d).oninput=()=>{chosenVehicle=null;renderVehicle();};renderVehicle();$('#hub-appt-form',d).onsubmit=async event=>{event.preventDefault();const b=$('#hub-appt-save',d);if(b.disabled)return;b.disabled=true;try{if(!chosenContact)throw Error('Choose a saved contact from the search results.');if($('#hub-appt-vehicle',d).value.trim()&&!chosenVehicle)throw Error('Choose a Vehicle Profile result or clear the vehicle search.');const minutes=Number($('#hub-appt-duration',d).value);if(!Number.isFinite(minutes)||minutes<5||minutes>1440)throw Error('Duration must be 5 to 1,440 minutes.');const s=H.atLocal($('#hub-appt-date',d).value,$('#hub-appt-time',d).value),a={...old,_owner:editOwner,id:old?.id||H.uid('APPT'),contactId:chosenContact.id,customerName:chosenContact.name,vehicleId:chosenVehicle?.id||'',vehicleLabel:vehicleLabel(chosenVehicle),title:chosenContact.name+' · '+$('#hub-appt-kind',d).value,start:s,end:new Date(Date.parse(s)+minutes*60000).toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,status:$('#hub-appt-status',d).value,kind:$('#hub-appt-kind',d).value,location:$('#hub-appt-location',d).value.trim(),notes:$('#hub-appt-notes',d).value.trim()};const collisions=H.overlap(await S.list('appointment'),a);if(collisions.length&&!confirm('This overlaps '+collisions.length+' appointment(s). Save anyway?'))return;await S.save('appointment',a);d.close();toast('Appointment saved; Drive sync queued.');await onSaved?.();await refresh();}catch(err){report(err,d);}finally{b.disabled=false;}};}
function contactVehicleIds(contact){return [...new Set([contact?.primaryVehicleId,...(Array.isArray(contact?.vehicleIds)?contact.vehicleIds:[])].filter(id=>vehicles.some(vehicle=>vehicle.id===id)))];}
