/* V0.9.4.89 chat-space, purchase-choice and composer-gesture polish. */
const SMART_MESSAGE_LIMIT=5,smartSuggestionCache=new Map();

function buyingMarkup(contact,{compact=false}={}){
  const values=H.buyingSummary(contact);
  return values.length?`<span class="hub-buying-summary ${compact?'compact':''}">${values.map(value=>`<span>${e(value)}</span>`).join('')}</span>`:'';
}

function nextCustomerAppointment(contactId){
  const now=Date.now()-60000;
  return appointments.filter(item=>item.contactId===contactId&&item.kind!=='Reminder'&&!item.deleted&&!['Completed','Cancelled','No show'].includes(item.status)&&Date.parse(item.end||item.start)>=now).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start))[0]||null;
}

function statusMeta(status='Tentative'){
  return ({Tentative:['🔴','tentative'],Booked:['🟡','booked'],Confirmed:['🟢','confirmed'],'Double Confirm':['🔵','double-confirm']})[status]||['⚪',String(status).toLowerCase().replace(/\s+/g,'-')];
}

function appointmentTimeRange(appointment){
  if(appointment?.timeTbd||appointment?.allDay)return'Time TBD';
  const start=Date.parse(appointment?.start),end=Date.parse(appointment?.end),startLabel=time(appointment?.start);
  return Number.isFinite(end)&&end>start?`${startLabel} – ${time(appointment.end)}`:startLabel;
}

function appointmentChipMarkup(contact){
  const appointment=nextCustomerAppointment(contact?.id);
  if(!appointment)return'';
  const [icon,cls]=statusMeta(appointment.status);
  return `<button type="button" class="hub-next-appointment ${e(cls)}" data-calendar-day="${e(H.localDay(appointment.start))}" aria-label="Open appointment day in Calendar"><span>🗓️ ${e(H.displayDate(appointment.start))} · ${e(appointmentTimeRange(appointment))}</span><b>${icon} ${e(appointment.status||'Tentative')}</b></button>`;
}

function vehicleFacts(vehicle){
  if(!vehicle)return'';
  const price=vehicle.price===''||vehicle.price===null||vehicle.price===undefined?'Price not set':'$'+fmt(vehicle.price);
  return `STK #${vehicle.stock||'—'} · ${fmt(vehicle.odometer)} ${vehicle.odometerUnit||'KM'} · ${price}`;
}

function interestedVehicleMarkup(contact,{compact=false,interactive=true,header=false}={}){
  const rows=interestedVehicles(contact),vehicle=rows[0],manual=String(contact?.interestedVehicleText||'').trim();
  if(!vehicle&&!manual)return'';
  const tag=interactive&&vehicle?'button':'div',open=interactive&&vehicle?` type="button" data-contact-vehicle="${e(vehicle.id)}"`:'';
  const name=vehicle?[vehicle.year,vehicle.make,vehicle.model].filter(Boolean).join(' ')||'Vehicle Profile':manual||'Interested Vehicle';
  const detail=vehicle?vehicleFacts(vehicle):'Interested Vehicle · not linked to Inventory';
  const count=rows.length+(manual&&vehicle?1:0);
  return `<${tag}${open} class="hub-interest-card ${compact?'compact':''} ${header?'header-card':''} ${vehicle?'linked':'manual'}"><span class="hub-interest-photo" ${vehicle?`data-vehicle-photo="${e(vehicle.id)}"`:''}></span><span class="hub-interest-copy"><strong>${e(name)}</strong><small>${e(detail)}</small>${manual&&vehicle?`<small>Looking for: ${e(manual)}</small>`:''}${buyingMarkup(contact,{compact:true})}</span>${count>1?`<b>+${count-1} more</b>`:interactive&&vehicle?'<span aria-hidden="true">›</span>':''}</${tag}>`;
}

function deviceRow(row){
  const contact=row.savedContact||row.contact,org=row.organization||contact,unread=row.unread?`<b class="hub-device-unread">${row.unread>99?'99+':row.unread}</b>`:'',target=row.live?`data-device-thread="${e(row.id)}"`:`data-device-contact="${e(contact.id)}"`,transport=row.live?row.preview||row.address||'Message':row.address||row.preview||'Saved contact';
  const interest=contact?interestedVehicleMarkup(contact,{compact:true,interactive:false}):'',detail=contact?(interest||buyingMarkup(contact,{compact:true})):`<small class="hub-device-preview">${e(transport)}</small>`;
  const identity=H.deviceIdentity(row.title,row.address,transport),title=identity.title,inlinePhone=identity.phone?`<small>${e(identity.phone)}</small>`:'';
  return `<article class="hub-device-row ${row.live?'live':'saved'} ${contact?'customer':''}" ${target} tabindex="0" aria-label="Open ${e(title)} conversation" style="--hub-color:${e(tint(org))}"><div class="hub-device-card-top"><div class="hub-device-identity-open"><span class="hub-device-identity-row"><strong>${e(title)}</strong>${inlinePhone}</span></div><span class="hub-time">${unread}${e(when(row.at))}</span><div class="hub-device-schedule-row"><span class="hub-tags">${categoryBadges(org)}</span>${contact?appointmentChipMarkup(contact):''}</div></div>${detail?`<div class="hub-device-detail-open">${detail}</div>`:''}</article>`;
}

function appointmentCard(appointment){
  const contact=contacts.find(row=>row.id===appointment.contactId);
  const vehicle=currentVehicle(appointment),[icon,cls]=statusMeta(appointment.status),identity=H.appointmentIdentity(appointment,contact),vehicleName=vehicle?[vehicle.year,vehicle.make,vehicle.model].filter(Boolean).join(' '):appointment.vehicleLabel||contact?.interestedVehicleText||'No vehicle linked';
  return `<div class="hub-appointment-entry"><div class="hub-calendar-time-range">${e(appointmentTimeRange(appointment))}</div><button type="button" class="hub-appointment customer-card ${e(cls)}" data-appt="${e(appointment.id)}" style="--hub-color:${e(tint(contact))}"><span class="hub-ap-photo" ${vehicle?`data-vehicle-photo="${e(vehicle.id)}"`:''}></span><span class="hub-ap-copy"><strong>${e(identity.primary)}${identity.phone?' · '+e(identity.phone):''}</strong><b>${e(vehicleName)}</b>${vehicle?`<span>${e(vehicleFacts(vehicle))}</span>`:''}${contact?buyingMarkup(contact,{compact:true}):''}<small>${e(appointment.appointmentType||appointment.kind||'Appointment')} · <em>${icon} ${e(appointment.status||'Tentative')}</em></small></span></button></div>`;
}

function reminderContact(reminder){return contacts.find(contact=>contact.id===reminder.contactId)||null;}
function reminderVehicle(reminder){return vehicles.find(vehicle=>vehicle.id===reminder.vehicleId)||null;}
function reminderComplete(reminder){return H.reminderComplete(reminder,new Date());}
function reminderMeta(reminder){
  const values=[];
  if(reminder.dailyRepeat)values.push('Daily');
  else if(reminder.dueDate)values.push(H.displayDate(reminder.dueDate));
  else values.push('No due date');
  if(reminder.dueTime)values.push(H.displayTime(reminder.dueTime));
  const contact=reminderContact(reminder),vehicle=reminderVehicle(reminder),identity=contact?.name||reminder.customerName||reminder.phone;
  if(identity)values.push(identity);
  if(vehicle||reminder.vehicleLabel)values.push(vehicle?vehicleLabel(vehicle):reminder.vehicleLabel);
  return values.join(' · ');
}
function reminderCalendarCard(reminder){
  const complete=reminderComplete(reminder);
  return `<div class="hub-reminder-calendar ${complete?'completed':''}"><button type="button" class="hub-reminder-check" data-reminder-toggle="${e(reminder.id)}" aria-label="${complete?'Mark reminder open':'Complete reminder'}">${complete?'✓':''}</button><button type="button" class="hub-reminder-calendar-copy" data-reminder="${e(reminder.id)}"><strong>${e(reminder.title||'Reminder')}</strong><small>${e([reminder.dueTime?H.displayTime(reminder.dueTime):'',reminderContact(reminder)?.name||reminder.customerName||'',reminderVehicle(reminder)?vehicleLabel(reminderVehicle(reminder)):reminder.vehicleLabel||''].filter(Boolean).join(' · '))}</small></button></div>`;
}
function reminderSort(left,right){
  const completeDifference=Number(reminderComplete(left))-Number(reminderComplete(right));
  if(completeDifference)return completeDifference;
  const leftDay=left.dueDate||'9999-12-31',rightDay=right.dueDate||'9999-12-31';
  return leftDay.localeCompare(rightDay)||(left.dueTime||'99:99').localeCompare(right.dueTime||'99:99')||String(left.title||'').localeCompare(String(right.title||''));
}
function notifyReminderChange(){window.dispatchEvent(new CustomEvent('lotkeys-reminder-change'));paintReminderFab();scheduleRefresh();}
function paintReminderFab(){const button=$('#hub-reminders',panel());if(!button)return;const state=H.reminderBellState(reminders,new Date());button.hidden=!state.visible;button.textContent=state.symbol;button.dataset.urgency=String(state.urgency);button.setAttribute('aria-label',`${state.count} active reminder${state.count===1?'':'s'}. Open reminders.`);button.title='Reminders';}
async function toggleReminderRecord(id,onChanged){
  await loadLocal();let reminder=await S.get('reminder',id)||reminders.find(row=>row.id===id);if(!reminder)return;
  if(!await S.get('reminder',id))reminder=await S.save('reminder',reminder);
  await S.save('reminder',H.toggleReminder(reminder,new Date()));
  await loadLocal();notifyReminderChange();await onChanged?.();
}

