  const extra=$('#hub-reminder-additional-fields',d),extraButton=$('#hub-reminder-additional',d),toggleExtra=show=>{extra.hidden=!show;extraButton.setAttribute('aria-expanded',String(show));$('b',extraButton).textContent=show?'−':'＋';};extraButton.onclick=()=>toggleExtra(extra.hidden);
